import { bundledModelPath } from "../engine/package-root.js";

export function draftOptions(modelPath: string = bundledModelPath()) {
  return { modelPath };
}

import { join } from "node:path";

export function childEnv(root: string) {
  const storageRoot = join(root, "sessions");
  return { ...process.env, RERAIL_HOME: join(root, "home"), RERAIL_STORAGE_ROOT: storageRoot };
}

/** Runs with its own `RERAIL_STORAGE_ROOT`; the root defaults to `<checkout>/.rerail/sessions`. */
export function isHealthCheck(env: NodeJS.ProcessEnv): boolean {
  return env.RERAIL_AUTOSTART === "0" && env.RERAIL_STORAGE_ROOT !== undefined;
}

import { resolve } from "node:path";
const PACKAGE_ROOT = resolve("/pkg");
export function bundledModelPath(): string {
  return resolve(PACKAGE_ROOT, "model");
}

export function op(operation: string) {
  if (operation === "model") return { operation };
  return { sessions: "sessions", dir: ".rerail" };
}

export function prepare(storageRoot: string): void {
  process.env.RERAIL_STORAGE_ROOT = storageRoot;
}

export function isHealthCheck(): boolean {
  return process.env.RERAIL_AUTOSTART === "0" && process.env.RERAIL_STORAGE_ROOT !== undefined;
}

import { resolveSessionPaths } from "../runtime/session-paths.js";

export function sessionPaths(workspaceRoot: string) {
  const { storageRoot, modelPath } = resolveSessionPaths(workspaceRoot);
  return { storageRoot, modelPath };
}

import { defaultStorageRoot } from "../runtime/session-paths.js";

export function ledgers(checkout: string): string {
  const sessions = defaultStorageRoot(checkout);
  return sessions;
}
